+                check_numbers(v)?;
+            }
+        }
+        Ok(())
+    }
+    match (v, doc) {
+        (Value::Object(o), ResponsesDoc::Request) => envelope(o, true, false),
+        (Value::Object(o), ResponsesDoc::Body) => envelope(o, false, false),
+        (Value::Object(o), ResponsesDoc::Event) => envelope(o, false, true),
+        _ => check_numbers(v),
+    }
+}
